<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { useToast } from 'vue-toastification'
import CurrencyApi, { type Currency, type CurrencyForm } from '@/api/currency'
import ErpField from '@/components/erp/ErpField.vue'
import ErpSearchField from '@/components/erp/ErpSearchField.vue'
import { confirmActionWarning } from '@/composables/useActionWarning'
import { moveCreatedRowFirst } from '@/utils/createdFirst'

type StatusFilter = 'all' | 'active' | 'inactive'
const { t } = useI18n(); const toast = useToast()
const search = ref(''); const status = ref<StatusFilter>('all'); const draftStatus = ref<StatusFilter>('all'); const filterOpen = ref(false)
const currencies = ref<Currency[]>([]); const loading = ref(false); const saving = ref(false); const dialog = ref(false); const deleting = ref<Currency | null>(null); const baseTarget = ref<Currency | null>(null); const editing = ref<Currency | null>(null); const errors = ref<Record<string, string>>({}); const initialForm = ref('')
const blank = (): CurrencyForm => ({ name: '', code: '', symbol: '', rate: 1, isActive: true, decimalPlaces: 2, isBase: false })
const form = ref<CurrencyForm>(blank())
const base = computed(() => currencies.value.find(item => item.isBase) ?? currencies.value[0])
const statusItems = computed(() => [{ title: t('pages.finance.currencies.currencies.allStatuses'), value: 'all' }, { title: t('pages.finance.currencies.currencies.activeOnly'), value: 'active' }, { title: t('pages.finance.currencies.currencies.inactiveOnly'), value: 'inactive' }])
const headers = computed(() => [{ title: t('common.fields.currency'), key: 'name', minWidth: '220px' }, { title: t('pages.finance.currencies.currencies.codeShortName'), key: 'code', minWidth: '110px' }, { title: t('pages.finance.currencies.currencies.symbol'), key: 'symbol', minWidth: '90px' }, { title: t('pages.finance.currencies.rateToBase', { currency: base.value?.code ?? t('common.messages.notAvailable') }), key: 'rate', minWidth: '190px' }, { title: t('pages.finance.currencies.currencies.decimals'), key: 'decimals', minWidth: '110px' }, { title: t('common.fields.status'), key: 'status', minWidth: '120px' }, { title: t('common.messages.actions'), key: 'actions', sortable: false, align: 'end' as const, minWidth: '92px' }])
const filtered = computed(() => { const q = search.value.trim().toLocaleLowerCase(); return currencies.value.filter(item => (!q || [item.name, item.code, item.symbol].some(value => String(value ?? '').toLocaleLowerCase().includes(q))) && (status.value === 'all' || status.value === 'active' && item.isActive || status.value === 'inactive' && !item.isActive)) })
const dirty = computed(() => JSON.stringify(form.value) !== initialForm.value)
async function load() { loading.value = true; try { currencies.value = (await CurrencyApi.getAll()).data } catch { toast.error(t('common.messages.failedToFetchCurrencies')) } finally { loading.value = false } }
function open(item?: Currency) { editing.value = item ?? null; errors.value = {}; form.value = item ? { name: item.name, code: item.code, symbol: item.symbol, rate: item.rate, isActive: item.isActive, decimalPlaces: item.decimalPlaces, isBase: item.isBase } : blank(); initialForm.value = JSON.stringify(form.value); dialog.value = true }
async function closeForm() { if (dirty.value && !await confirmActionWarning({ key: 'discard-form-changes', title: t('common.actionWarnings.discardTitle'), message: t('common.actionWarnings.discardMessage'), confirmText: t('common.actionWarnings.discardConfirm'), cancelText: t('common.actions.cancel'), icon: 'tabler-file-alert', tone: 'primary' })) return; dialog.value = false }
async function save() { if (!form.value.name?.trim() || !form.value.code?.trim()) return; saving.value = true; errors.value = {}; try { const newRow = !editing.value; const result = editing.value ? await CurrencyApi.update(editing.value.id, form.value) : await CurrencyApi.create(form.value); dialog.value = false; await load(); if (newRow) currencies.value = moveCreatedRowFirst(currencies.value, result.data); toast.success(t(editing.value ? 'pages.finance.currencies.currencies.currencyUpdatedSuccessfully' : 'pages.finance.currencies.currencies.currencyCreatedSuccessfully')) } catch (error: any) { errors.value = error.errors ?? {}; toast.error(error.message ?? t('pages.finance.currencies.currencies.nameAndCodeAreRequired')) } finally { saving.value = false } }
async function remove() { if (!deleting.value) return; saving.value = true; try { await CurrencyApi.delete(deleting.value.id); deleting.value = null; await load() } catch (error: any) { toast.error(error.message) } finally { saving.value = false } }
async function toggle(item: Currency) { if (item.isBase) return; try { await CurrencyApi.update(item.id, { isActive: !item.isActive }); await load() } catch (error: any) { toast.error(error.message) } }
async function makeBase() { if (!baseTarget.value) return; saving.value = true; try { await CurrencyApi.update(baseTarget.value.id, { isBase: true }); baseTarget.value = null; await load() } catch (error: any) { toast.error(error.message) } finally { saving.value = false } }
function applyFilters() { status.value = draftStatus.value; filterOpen.value = false }; function resetFilters() { status.value = 'all'; draftStatus.value = 'all'; filterOpen.value = false }
onMounted(load)
</script>

<template>
  <div class="currency-workspace"><div class="currency-workspace__heading"><VBreadcrumbs :items="[{ title: t('erp.home'), to: { name: 'home' } }, { title: t('common.navigation.options'), disabled: true }, { title: t('common.navigation.finance'), disabled: true }]" density="compact" class="pa-0" /><h1 class="text-h5 font-weight-bold mb-0">{{ t('pages.finance.currencies.currencies.currencyManagement') }}</h1></div><VCard class="currency-panel"><VCardText class="currency-toolbar pa-4"><VRow align="center" class="ma-0"><VCol cols="12" md="6" lg="5" class="pa-0"><ErpSearchField v-model="search" :placeholder="t('pages.finance.currencies.currencies.searchByNameShortCodeOrSymbol')" /></VCol><VCol cols="12" md="6" lg="7" class="d-flex flex-wrap justify-md-end ga-2 pa-0 pt-3 pt-md-0"><DataTableFilterMenu v-model="filterOpen" :active="status !== 'all'" :show-reset="false" @update:model-value="open => { if (open) draftStatus = status }"><ErpField v-model="draftStatus" kind="select" :items="statusItems" :label="t('common.fields.status')" :placeholder="t('common.fields.status')" /><template #actions><VBtn class="currency-filter-reset" variant="flat" @click="resetFilters">{{ t('common.messages.reset') }}</VBtn><VBtn color="primary" variant="flat" @click="applyFilters">{{ t('educational.apply') }}</VBtn></template></DataTableFilterMenu><VBtn class="currency-add" prepend-icon="tabler-plus" @click="open()">{{ t('pages.finance.currencies.currencies.addCurrency') }}</VBtn></VCol></VRow></VCardText><ResponsiveDataTable :headers="headers" :items="filtered" :loading="loading" :skeleton-rows="6" item-value="id" class="currency-table" mobile-cards mobile-expand-all mobile-title-key="name" mobile-action-key="actions" :sticky-key-column="false" :sticky-action-column="false"><template #item.name="{ item }"><div class="d-flex align-center ga-2"><span>{{ item.name }}</span><VChip v-if="item.isBase" size="x-small" color="warning" variant="tonal" prepend-icon="tabler-star">{{ t('common.messages.baseCurrency') }}</VChip></div></template><template #item.code="{ item }"><VChip size="small" variant="outlined" color="primary">{{ item.code }}</VChip></template><template #item.symbol="{ item }">{{ item.symbol || '—' }}</template><template #item.rate="{ item }"><span v-if="item.isBase" class="text-success font-weight-bold">{{ t('pages.finance.currencies.baseRate') }}</span><span v-else>1 {{ base?.code }} = {{ item.rate }} {{ item.code }}</span></template><template #item.decimals="{ item }">{{ item.decimalPlaces }}</template><template #item.status="{ item }"><VChip :color="item.isActive ? 'success' : 'secondary'" size="small" variant="tonal" :class="{ 'cursor-pointer': !item.isBase }" @click="toggle(item)">{{ item.isActive ? t('common.statuses.active') : t('common.statuses.inactive') }}</VChip></template><template #item.actions="{ item }"><VMenu location="bottom end"><template #activator="{ props }"><VBtn v-bind="props" icon="tabler-dots-vertical" size="small" variant="tonal" /></template><VList density="compact"><VListItem v-if="!item.isBase" prepend-icon="tabler-star" :title="t('pages.finance.currencies.currencies.setAsBaseCurrency')" @click="baseTarget = item" /><VListItem prepend-icon="tabler-pencil" :title="t('common.actions.edit')" @click="open(item)" /><VListItem v-if="!item.isBase" prepend-icon="tabler-trash" class="currency-table__delete" :title="t('common.actions.delete')" @click="deleting = item" /></VList></VMenu></template><template #no-data><div class="currency-empty"><TableEmptyState icon="tabler-currency-off" :min-height="0" :title="t('$vuetify.noDataText')" :description="search || status !== 'all' ? t('$vuetify.dataIterator.noResultsText') : t('pages.finance.currencies.currencies.noCurrenciesFoundMatchingYourSearch')" /></div></template></ResponsiveDataTable></VCard></div>
  <VDialog :model-value="dialog" max-width="760" scrollable content-class="currency-editor-overlay" @update:model-value="value => { if (!value) void closeForm() }"><VCard class="currency-editor"><VCardTitle class="currency-editor__header px-5 py-4"><span>{{ t(editing ? 'common.actions.editItem' : 'common.actions.addItem', { item: t('common.fields.currency') }) }}</span><VSpacer /><VBtn icon="tabler-x" variant="tonal" color="error" class="currency-editor__close" :disabled="saving" @click="closeForm" /></VCardTitle><VCardText class="currency-editor__body pa-5"><VForm @submit.prevent="save"><VRow><VCol cols="12" md="6"><ErpField v-model="form.name" required :label="t('pages.finance.currencies.currencies.currencyName')" :placeholder="t('pages.finance.currencies.currencies.currencyName')" :error-messages="errors.name" /></VCol><VCol cols="12" md="6"><ErpField v-model="form.code" required :label="t('pages.finance.currencies.currencies.codeShortName')" :placeholder="t('pages.finance.currencies.currencies.codeShortName')" maxlength="5" :error-messages="errors.code" /></VCol><VCol cols="12" md="4"><ErpField v-model="form.symbol" :label="t('pages.finance.currencies.currencies.symbol')" :placeholder="t('pages.finance.currencies.currencies.symbol')" :error-messages="errors.symbol" /></VCol><VCol cols="12" md="4"><ErpField v-model.number="form.decimalPlaces" type="number" min="0" max="6" :label="t('pages.finance.currencies.currencies.decimalPrecision')" :placeholder="t('pages.finance.currencies.currencies.decimalPrecision')" /></VCol><VCol cols="12" md="4"><ErpField v-model.number="form.rate" type="number" min="0.00000001" step="0.00000001" :disabled="form.isBase" :label="t('pages.finance.currencies.rateToBase', { currency: base?.code ?? 'BASE' })" :placeholder="t('pages.finance.currencies.rateToBase', { currency: base?.code ?? 'BASE' })" /></VCol><VCol cols="12" md="6"><VSwitch v-model="form.isBase" color="primary" inset :label="t('pages.finance.currencies.currencies.setAsPrimaryBase')" hide-details /></VCol><VCol cols="12" md="6"><VSwitch v-model="form.isActive" color="success" inset :disabled="form.isBase" :label="t('pages.finance.currencies.currencies.activeStatus')" hide-details /></VCol></VRow></VForm></VCardText><VCardActions class="currency-editor__footer justify-end px-5 py-4"><VBtn class="currency-editor__cancel" :disabled="saving" @click="closeForm">{{ t('common.actions.cancel') }}</VBtn><VBtn class="currency-editor__save" :loading="saving" :disabled="!form.name.trim() || !form.code.trim()" @click="save">{{ t('common.actions.save') }}</VBtn></VCardActions></VCard></VDialog>
  <VDialog :model-value="Boolean(deleting)" max-width="480" content-class="currency-delete-overlay" @update:model-value="value => { if (!value) deleting = null }"><VCard class="currency-confirm"><VCardText class="currency-confirm__content"><div class="currency-confirm__icon"><VIcon icon="tabler-trash" size="30" /></div><h2>{{ t('common.actions.delete') }}</h2><p>{{ t('common.confirmations.areYouSureYouWantToDelete') }} {{ deleting?.name }}. {{ t('common.confirmations.thisActionCannotBeUndone') }}</p></VCardText><VCardActions class="currency-confirm__actions"><VBtn class="currency-editor__cancel" :disabled="saving" @click="deleting = null">{{ t('common.actions.cancel') }}</VBtn><VBtn class="currency-confirm__delete" :loading="saving" @click="remove">{{ t('common.actions.delete') }}</VBtn></VCardActions></VCard></VDialog>
  <VDialog :model-value="Boolean(baseTarget)" max-width="480" content-class="currency-base-overlay" @update:model-value="value => { if (!value) baseTarget = null }"><VCard class="currency-confirm"><VCardText class="currency-confirm__content"><div class="currency-confirm__icon currency-confirm__icon--primary"><VIcon icon="tabler-star" size="30" /></div><h2>{{ t('pages.finance.currencies.currencies.changeBaseCurrencyTitle') }}</h2><p>{{ t('pages.finance.currencies.currencies.changeBaseCurrencyWarning', { currency: baseTarget?.code }) }}</p></VCardText><VCardActions class="currency-confirm__actions"><VBtn class="currency-editor__cancel" :disabled="saving" @click="baseTarget = null">{{ t('common.actions.cancel') }}</VBtn><VBtn class="currency-editor__save" :loading="saving" @click="makeBase">{{ t('pages.finance.currencies.currencies.confirmSetAsBaseCurrency') }}</VBtn></VCardActions></VCard></VDialog>
</template>

<style lang="scss">
.currency-workspace { display:flex; flex-direction:column; gap:.75rem; }.currency-workspace__heading { display:flex; flex-direction:column; gap:.15rem; }.currency-workspace__heading h1 { line-height:1.35; }.currency-panel { overflow:hidden; border:1px solid rgba(var(--v-border-color),var(--v-border-opacity)); border-radius:.9rem; }.currency-toolbar { border-block-end:1px solid rgba(var(--v-border-color),var(--v-border-opacity)); }.currency-add,.currency-editor__save { background:rgb(var(--v-theme-primary))!important; color:rgb(var(--v-theme-on-primary))!important; }.currency-filter-reset { border:1px solid rgba(var(--v-theme-primary),.35)!important; background:rgba(var(--v-theme-primary),.13)!important; color:rgb(var(--v-theme-primary))!important; }.currency-filter-reset:hover { background:rgb(var(--v-theme-primary))!important; color:rgb(var(--v-theme-on-primary))!important; }.currency-table .v-table__wrapper>table { min-inline-size:1000px; }.currency-table .v-table__wrapper>table>thead>tr>th { background:rgba(var(--v-theme-on-surface),.045); font-size:.82rem; font-weight:700; white-space:nowrap; }.currency-table .v-table__wrapper>table>tbody>tr>td { white-space:nowrap; }.currency-table .v-table__wrapper:has(.currency-empty) { overflow-x:hidden; }.currency-table .v-table__wrapper>table:has(.currency-empty) { min-inline-size:100%; }.currency-empty { display:grid; min-block-size:17rem; place-items:center; }.currency-table__delete { color:rgb(var(--v-theme-error))!important; }.cursor-pointer { cursor:pointer; }.currency-editor,.currency-confirm { overflow:hidden; background:rgb(var(--v-theme-surface)); }.currency-editor__header,.currency-editor__footer { display:flex; align-items:center; border-color:rgba(var(--v-border-color),.52); border-style:solid; border-width:0; background:color-mix(in srgb,rgb(var(--v-theme-surface)) 93%,rgb(var(--v-theme-on-surface)) 7%); }.currency-editor__header { border-block-end-width:1px; font-size:1.2rem; font-weight:700; }.currency-editor__footer { gap:.75rem; border-block-start-width:1px; }.currency-editor__body { background:rgba(var(--v-theme-on-surface),.018); }.currency-editor__close { border:1px solid rgba(var(--v-theme-error),.4)!important; border-radius:999px!important; }.currency-editor__cancel { border:1px solid rgba(var(--v-theme-secondary),.5)!important; background:rgba(var(--v-theme-secondary),.13)!important; color:rgb(var(--v-theme-secondary))!important; }.currency-confirm__content { display:flex; flex-direction:column; align-items:center; padding:2rem 2rem 1.25rem!important; text-align:center; }.currency-confirm__content h2 { margin:0; font-size:1.2rem; }.currency-confirm__content p { max-inline-size:22rem; margin:.65rem 0 0; color:rgba(var(--v-theme-on-surface),var(--v-medium-emphasis-opacity)); }.currency-confirm__icon { display:grid; inline-size:4.25rem; block-size:4.25rem; margin-block-end:1.25rem; border-radius:50%; background:rgba(var(--v-theme-error),.14); color:rgb(var(--v-theme-error)); place-items:center; }.currency-confirm__icon--primary { background:rgba(var(--v-theme-primary),.14); color:rgb(var(--v-theme-primary)); }.currency-confirm__actions { display:grid!important; grid-template-columns:repeat(2,minmax(0,1fr)); gap:.75rem; padding:0 2rem 2rem!important; }.currency-confirm__actions .v-btn { min-block-size:2.85rem; }.currency-confirm__delete { background:rgb(var(--v-theme-error))!important; color:rgb(var(--v-theme-on-error))!important; }.v-overlay:has(.currency-editor-overlay) .v-overlay__scrim,.v-overlay:has(.currency-delete-overlay) .v-overlay__scrim,.v-overlay:has(.currency-base-overlay) .v-overlay__scrim { background:rgba(20,25,35,.3)!important; backdrop-filter:blur(6px); opacity:1!important; }
</style>
